transitions.transitionKernelCode:
export default TransitionKernel((input, parameters) => {
  const pc = input["PlanClock"][0];
  const m = input["DemandOutlook"][0];
  const p1 = input["InventoryPosition_IngredientA"][0];
  const p2 = input["InventoryPosition_IngredientB"][0];
  // Make-to-forecast: expected demand over the coming plan
  // period at the current arrival rate, in units (mixture
  // mean order size), blended by forecast_weight with the
  // fixed-plan batch carried on the clock: 0 follows the
  // fixed plan, 1 fully tracks demand. Uses stored attributes
  // and parameters only, since a fresh Distribution sample
  // cannot sit inside arithmetic.
  const qtyPerOrder = parameters.small_share * parameters.small_qty_mean + (1 - parameters.small_share) * parameters.bulk_qty_mean;
  const forecastQty = Math.max(m.rate, 0) * parameters.plan_period * qtyPerOrder;
  const produce = Math.max((1 - parameters.forecast_weight) * pc.qty + parameters.forecast_weight * forecastQty, 100);
  const need1 = produce * parameters.bom_ingredient_a_per_unit;
  const need2 = produce * parameters.bom_ingredient_b_per_unit;
  return {
    "PlanClock": [{ remaining: parameters.plan_period, qty: Distribution.Gaussian(parameters.batch_qty_mean, parameters.batch_qty_sd) }],
    "ProductionOrdersWaiting": [{ produce_qty: produce, consume_ingredient_a: need1, consume_ingredient_b: need2, waited: 0 }],
    "InventoryPosition_IngredientA": [{ position: p1.position - need1 }],
    "InventoryPosition_IngredientB": [{ position: p2.position - need2 }],
  };
});

